import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parents[1]
REPO = ROOT.parents[2]

def view(path, start=1, end=None):
    p = REPO / path
    lines = p.read_text(encoding='utf-8-sig').splitlines()
    end = len(lines) if end is None else min(end, len(lines))
    print(f'FILE {path} L{start}-{end}/{len(lines)}')
    for i in range(start-1, end):
        print(f'{i+1}: {lines[i]}')

def refs(items):
    return '; '.join(x['path']+':'+str(x.get('lines', '')) for x in items)

def handoff(mode, start, end):
    f = json.loads((ROOT/'tasks/R7-M01/forward-map.json').read_text())
    if mode == 'facts':
        for x in f['facts'][start-1:end]:
            print(x['id'],x['status'],x['fact'],'SOURCE='+refs(x['source']),'SPEC='+refs(x['specification']),x.get('qualification',''))
    elif mode == 'dispositions':
        for i,x in enumerate(f['source_unit_dispositions'][start-1:end], start):
            print(i,x['path'],x['lines'],x['disposition'],','.join(x['fact_ids']),x['reason'])
    elif mode == 'reverse':
        c=json.loads((ROOT/'tasks/R7-M01/reverse-map.json').read_text())['clauses']
        for x in c[start-1:end]:
            print(x['id'],refs([x['clause']]),x['context_label'],x['status'],'SOURCE='+refs(x['source']),x.get('cross_reference_note'))

if __name__=='__main__':
    if sys.argv[1]=='view':
        view(sys.argv[2],int(sys.argv[3]) if len(sys.argv)>3 else 1,int(sys.argv[4]) if len(sys.argv)>4 else None)
    else:
        handoff(sys.argv[1],int(sys.argv[2]),int(sys.argv[3]))


